 "content": "def transform(grid):
    # Extend repeated off-pattern payload colors along their aligned axes,
    # filling only empty cells between matching payload blocks.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Tile payload centers are contiguous same-color blocks; treat each such
    # block as a marker and connect aligned blocks of the same color.
    blocks = []
    seen = set()
    from collections import deque, Counter
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if not v or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(cells)>1:
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                blocks.append((v,min(rs),max(rs),min(cs),max(cs)))
    # The exceptional payload colors occur as repeated blocks; connect
    # neighboring blocks sharing a row band or column band.
    for i,a in enumerate(blocks):
        va, ar0,ar1,ac0,ac1=a
        for b in blocks[i+1:]:
            vb,br0,br1,bc0,bc1=b
            if va!=vb: continue
            if ar0==br0 and ar1==br1 and ac1<bc0:
                for y in range(ar0,ar1+1):
                    for x in range(ac1+1,bc0):
                        if out[y][x]==0: out[y][x]=va
            elif ac0==bc0 and ac1==bc1 and ar1<br0:
                for y in range(ar1+1,br0):
                    for x in range(ac0,ac1+1):
                        if out[y][x]==0: out[y][x]=va
    return out
